        const start = new Date(subscription.currentPeriodEnd);
        subscription = await subscriptions.setSubscriptionPeriod(subscription.orgId, {
          currentPeriodStart: toIsoTimestamp(start), currentPeriodEnd: toIsoTimestamp(periodEnd(start, subscription.interval)),
        });
        if (subscription.plan !== "free") await issueInvoice(subscription, fullCharge(subscription), now);
        result.processed++;
      }
    }
  });
}
